package store.cadera.cdrjobs.listener;
import net.kyori.adventure.text.Component;import org.bukkit.*;import org.bukkit.entity.*;import org.bukkit.event.*;import org.bukkit.event.player.*;import org.bukkit.inventory.ItemStack;import store.cadera.cdrjobs.CdrJobsPlugin;import store.cadera.cdrjobs.api.*;import store.cadera.cdrjobs.api.event.ProfessionActionEvent;import store.cadera.cdrjobs.model.*;import store.cadera.cdrjobs.service.*;import java.util.*;import java.util.concurrent.ConcurrentHashMap;
public final class FisherListener implements Listener{private static final Set<Material>TREASURE=EnumSet.of(Material.BOW,Material.ENCHANTED_BOOK,Material.FISHING_ROD,Material.NAME_TAG,Material.NAUTILUS_SHELL,Material.SADDLE);private final CdrJobsPlugin plugin;private final ProgressionService progression;private final FisherService fisher;private final LevelService levels;private final Map<UUID,MoveState>movement=new ConcurrentHashMap<>();private Map<Material,Integer>xp=new HashMap<>();public FisherListener(CdrJobsPlugin p,ProgressionService pr,FisherService f,LevelService l){plugin=p;progression=pr;fisher=f;levels=l;refreshXpMap();}public void refreshXpMap(){xp=plugin.loadActivityXp("fisher.xp");}@EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void move(PlayerMoveEvent e){if(e.getTo()==null)return;MoveState s=movement.get(e.getPlayer().getUniqueId());if(s==null||!s.anchor.getWorld().equals(e.getTo().getWorld())||s.anchor.distanceSquared(e.getTo())>=4)movement.put(e.getPlayer().getUniqueId(),new MoveState(e.getTo(),System.currentTimeMillis()));}@EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void fish(PlayerFishEvent e){if(!plugin.getConfig().getBoolean("fisher.enabled",true)||e.getState()!=PlayerFishEvent.State.CAUGHT_FISH)return;Player p=e.getPlayer();if(afk(p)){p.sendActionBar(Component.text("✦ Tidebound • move around to resume profession rewards"));return;}if(!(e.getCaught() instanceof Item item))return;ItemStack stack=item.getItemStack();Material mat=stack.getType();boolean treasure=TREASURE.contains(mat);Integer base=xp.get(mat);if(base==null){if(!treasure)return;base=plugin.getConfig().getInt("fisher.treasure-xp",20);}boolean ocean=p.getLocation().getBlock().getBiome().name().contains("OCEAN");fisher.recordCatch(p,treasure,ocean);plugin.getServer().getPluginManager().callEvent(new ProfessionActionEvent(p,JobType.FISHER,ProfessionActionType.CATCH_FISH,1));long amount=fisher.applyXp(p,Math.max(1,Math.round(base*Math.max(0,plugin.getConfig().getDouble("fisher.xp-multiplier",1)))),ocean,treasure);JobProgress pr=progression.addXp(p,JobType.FISHER,amount);if(plugin.getConfig().getBoolean("settings.actionbar-xp",true)){long req=levels.xpRequiredForNextLevel(pr.level());p.sendActionBar(Component.text(pr.level()>=levels.maxLevel()?"✦ Tidebound Angler Lv."+levels.maxLevel()+" • MAX":"✦ Tidebound +"+amount+" XP • Lv."+pr.level()+" • "+pr.xp()+"/"+req));}}@EventHandler public void quit(PlayerQuitEvent e){movement.remove(e.getPlayer().getUniqueId());}private boolean afk(Player p){long now=System.currentTimeMillis();MoveState s=movement.computeIfAbsent(p.getUniqueId(),u->new MoveState(p.getLocation(),now));return now-s.lastMoved>=Math.max(60,plugin.getConfig().getLong("fisher.anti-exploit.afk-after-seconds",600))*1000;}private record MoveState(Location anchor,long lastMoved){}
}
